// AgentWorkServiceHandler is an implementation of the talgent.agent.public.v1.AgentWorkService
// service.
type AgentWorkServiceHandler interface {
	// ChangeWorkAgentAppearance changes the name and icon of the Work Agent that
	// represents the caller; only that human may change it.
	ChangeWorkAgentAppearance(context.Context, *connect.Request[v1.ChangeWorkAgentAppearanceRequest]) (*connect.Response[v1.ChangeWorkAgentAppearanceResponse], error)
	// GetMyWorkAgent reads the caller's Work Agent, or the appearance it would
	// start with when the caller has none yet; it never creates one.
	GetMyWorkAgent(context.Context, *connect.Request[v1.GetMyWorkAgentRequest]) (*connect.Response[v1.GetMyWorkAgentResponse], error)
	// EnsureMyWorkAgent returns the caller's Work Agent, establishing it when
	// the caller has none yet.
	EnsureMyWorkAgent(context.Context, *connect.Request[v1.EnsureMyWorkAgentRequest]) (*connect.Response[v1.EnsureMyWorkAgentResponse], error)
	// GetAgentSoul reads an Agent's Soul; only one of its Owners may read it.
	GetAgentSoul(context.Context, *connect.Request[v1.GetAgentSoulRequest]) (*connect.Response[v1.GetAgentSoulResponse], error)
	// ChangeAgentSoul replaces an Agent's Soul; only one of its Owners may. Each
	// of its Works takes it up at its next start; running Turns are unaffected.
	ChangeAgentSoul(context.Context, *connect.Request[v1.ChangeAgentSoulRequest]) (*connect.Response[v1.ChangeAgentSoulResponse], error)
	// GetWorkCapabilities reads actual Harness candidates and their latest updates.
	GetWorkCapabilities(context.Context, *connect.Request[v1.GetWorkCapabilitiesRequest]) (*connect.Response[v1.GetWorkCapabilitiesResponse], error)
	// GetWorkPluginResults reads installation and loading projections for selected plugins.
	GetWorkPluginResults(context.Context, *connect.Request[v1.GetWorkPluginResultsRequest]) (*connect.Response[v1.GetWorkPluginResultsResponse], error)
	// GetWorkServiceAccess reads fixed selection and latest safe supply feedback.
	GetWorkServiceAccess(context.Context, *connect.Request[v1.GetWorkServiceAccessRequest]) (*connect.Response[v1.GetWorkServiceAccessResponse], error)
	// CancelTurn interrupts only the addressed turn, leaving the Work running.
	// It answers Unavailable while the Work's execution environment is not
	// observed, such as during a Disconnection.
	CancelTurn(context.Context, *connect.Request[v1.CancelTurnRequest]) (*connect.Response[v1.CancelTurnResponse], error)
	// GetCurrentTurn reads native activity independently of paginated history.
	// It answers Unavailable while the Work's execution environment is not
	// observed, such as during a Disconnection.
	GetCurrentTurn(context.Context, *connect.Request[v1.GetCurrentTurnRequest]) (*connect.Response[v1.GetCurrentTurnResponse], error)
	// ListPendingInteractions reads the Harness requests awaiting the user's reply,
	// independently of paginated message history. It answers Unavailable while
	// the Work's execution environment is not observed.
	ListPendingInteractions(context.Context, *connect.Request[v1.ListPendingInteractionsRequest]) (*connect.Response[v1.ListPendingInteractionsResponse], error)
	// GetWork reads the caller's own Work without changing the record.
	GetWork(context.Context, *connect.Request[v1.GetWorkRequest]) (*connect.Response[v1.GetWorkResponse], error)
	// ChangeWorkVisibility switches the caller's own Work between private and
	// public within its Project. A project-scoped definition's Work keeps its
	// visibility.
	ChangeWorkVisibility(context.Context, *connect.Request[v1.ChangeWorkVisibilityRequest]) (*connect.Response[v1.ChangeWorkVisibilityResponse], error)
	// RevokeWorkShare stops one reader from reading the caller's own Work; that
	// reader's open message streams end at once. Granting goes through the
	// caller that knows the Work's Project members.
	RevokeWorkShare(context.Context, *connect.Request[v1.RevokeWorkShareRequest]) (*connect.Response[v1.RevokeWorkShareResponse], error)
	// ListWorkLifecycleEvents reads the Work's lifecycle transitions for its continuous timeline.
	ListWorkLifecycleEvents(context.Context, *connect.Request[v1.ListWorkLifecycleEventsRequest]) (*connect.Response[v1.ListWorkLifecycleEventsResponse], error)
	// StopWork requests normal stop of the observed execution.
	StopWork(context.Context, *connect.Request[v1.StopWorkRequest]) (*connect.Response[v1.StopWorkResponse], error)
	// ResumeWork explicitly resumes the fixed assignee's stopped conversation.
	ResumeWork(context.Context, *connect.Request[v1.ResumeWorkRequest]) (*connect.Response[v1.ResumeWorkResponse], error)
	// RestartWork retries a Failed Work using its existing native Session when present.
	RestartWork(context.Context, *connect.Request[v1.RestartWorkRequest]) (*connect.Response[v1.RestartWorkResponse], error)
	// ArchiveWork permanently closes an eligible stopped or failed conversation.
	ArchiveWork(context.Context, *connect.Request[v1.ArchiveWorkRequest]) (*connect.Response[v1.ArchiveWorkResponse], error)
	// SendMessage delivers ordinary input to an existing AgentWork.
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest]) (*connect.Response[v1.SendMessageResponse], error)
	// RespondToInteraction replies to the current required interaction.
	RespondToInteraction(context.Context, *connect.Request[v1.RespondToInteractionRequest]) (*connect.Response[v1.RespondToInteractionResponse], error)
	// SetThinkingLevel adjusts the current Work Harness and retains its accepted setting.
	SetThinkingLevel(context.Context, *connect.Request[v1.SetThinkingLevelRequest]) (*connect.Response[v1.SetThinkingLevelResponse], error)
	// GetThinkingLevel reads the retained setting for an accessible Work in any state.
	GetThinkingLevel(context.Context, *connect.Request[v1.GetThinkingLevelRequest]) (*connect.Response[v1.GetThinkingLevelResponse], error)
	// SetPermissionMode changes the permission mode of a running Work on a
	// Managed Computer at once and retains the mode its Harness accepted for
	// the Work's later starts.
	SetPermissionMode(context.Context, *connect.Request[v1.SetPermissionModeRequest]) (*connect.Response[v1.SetPermissionModeResponse], error)
}

